    if (e.data && e.data.type === "close-tab-switcher") {
      destroyOverlay();
    }
  });

  chrome.runtime.onMessage.addListener((msg, sender, sendResponse) => {
    if (msg.type === "open-tab-switcher-overlay") {
      createOverlay();
      sendResponse({ ok: true });
      return true;
    }
  });
})();

