      if (getState('nor1c-location-blocker')) {
        if (typeof error === 'function') error({ code: 1, message: 'Geolocation blocked by extension' });
        return 0;
      }
      return nativeGeolocation.watchPosition.apply(nativeGeolocation, arguments);
    },
