    '[aria-label*="cookie" i][role="dialog"]',
    '[aria-label*="consent" i][role="dialog"]',
    '[aria-label*="privacy" i][role="dialog"]'
  ].join(',\n') + ' { display: none !important; visibility: hidden !important; pointer-events: none !important; }';

  let active = null;
  let style = null;
  let observer = null;
  let clickTimer = null;

  const REJECT_PATTERNS = [
    /reject\s*all/i,
    /decline\s*all/i,
    /refuse\s*all/i,
    /deny\s*all/i,
    /reject\s*cookies/i,
    /decline\s*cookies/i,
    /refuse\s*cookies/i,
    /only\s*necessary/i,
    /only\s*essential/i,
    /necessary\s*only/i,
    /essential\s*only/i,
    /alle\s*ablehnen/i,
